CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE sources(id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL UNIQUE,grade TEXT NOT NULL DEFAULT 'A',enabled INTEGER NOT NULL DEFAULT 1,scope TEXT NOT NULL,last_success TEXT,last_error TEXT);
CREATE TABLE snapshots(id TEXT PRIMARY KEY,source_id TEXT REFERENCES sources(id),url TEXT NOT NULL,title TEXT NOT NULL,publisher TEXT NOT NULL,published TEXT,fetched_at TEXT NOT NULL,hash TEXT NOT NULL,body TEXT NOT NULL,paragraphs TEXT NOT NULL,scope TEXT NOT NULL,document_type TEXT NOT NULL,previous_id TEXT REFERENCES snapshots(id),asset_id TEXT,UNIQUE(url,hash));
CREATE INDEX snapshots_date ON snapshots(published);
CREATE TABLE claims(id TEXT PRIMARY KEY,snapshot_id TEXT NOT NULL REFERENCES snapshots(id),text TEXT NOT NULL,quote TEXT NOT NULL,paragraph_id TEXT NOT NULL,scope TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',reason TEXT NOT NULL DEFAULT '',revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE INDEX claims_snapshot ON claims(snapshot_id);
CREATE TABLE verifications(id TEXT PRIMARY KEY,claim_id TEXT REFERENCES claims(id),status TEXT NOT NULL,reason TEXT NOT NULL,scope_confirmed INTEGER NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE topics(id TEXT PRIMARY KEY,snapshot_id TEXT NOT NULL REFERENCES snapshots(id),title TEXT NOT NULL,summary TEXT NOT NULL,angle TEXT NOT NULL,audience TEXT NOT NULL,scores TEXT NOT NULL,reasons TEXT NOT NULL,total REAL NOT NULL,status TEXT NOT NULL DEFAULT '待评估',favorite INTEGER NOT NULL DEFAULT 0,deferred INTEGER NOT NULL DEFAULT 0,note TEXT NOT NULL DEFAULT '',revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,UNIQUE(snapshot_id,title));
CREATE TABLE projects(id TEXT PRIMARY KEY,topic_id TEXT REFERENCES topics(id),title TEXT NOT NULL,scope TEXT NOT NULL,snapshot_ids TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,archived INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE versions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),kind TEXT NOT NULL,number INTEGER NOT NULL,parent_id TEXT REFERENCES versions(id),master_id TEXT REFERENCES versions(id),body TEXT NOT NULL,dependency_hash TEXT NOT NULL,stale INTEGER NOT NULL DEFAULT 0,origin TEXT NOT NULL,job_id TEXT,created_at TEXT NOT NULL,UNIQUE(project_id,kind,number),UNIQUE(job_id,kind));
CREATE TABLE version_claims(version_id TEXT REFERENCES versions(id),claim_id TEXT REFERENCES claims(id),PRIMARY KEY(version_id,claim_id));
CREATE TABLE reviews(id TEXT PRIMARY KEY,version_id TEXT NOT NULL REFERENCES versions(id),dependency_hash TEXT NOT NULL,decision TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE assets(id TEXT PRIMARY KEY,path TEXT NOT NULL UNIQUE,name TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,hash TEXT NOT NULL,kind TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE artifacts(id TEXT PRIMARY KEY,asset_id TEXT NOT NULL REFERENCES assets(id),target_id TEXT NOT NULL,mode TEXT NOT NULL,format TEXT NOT NULL,manifest TEXT NOT NULL,quality TEXT NOT NULL,job_id TEXT,created_at TEXT NOT NULL,UNIQUE(job_id,format));
CREATE TABLE jobs(id TEXT PRIMARY KEY,type TEXT NOT NULL,state TEXT NOT NULL,stage TEXT NOT NULL,input TEXT NOT NULL,input_hash TEXT NOT NULL,idempotency_key TEXT UNIQUE NOT NULL,attempt INTEGER NOT NULL DEFAULT 0,lease_owner TEXT,lease_until TEXT,fence INTEGER NOT NULL DEFAULT 0,checkpoint TEXT NOT NULL DEFAULT '{}',result TEXT,error TEXT,cancel_requested INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,started_at TEXT,finished_at TEXT);
CREATE INDEX jobs_state ON jobs(state,created_at);
CREATE TABLE events(job_id TEXT NOT NULL REFERENCES jobs(id),seq INTEGER NOT NULL,type TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(job_id,seq));
CREATE TABLE reports(id TEXT PRIMARY KEY,date TEXT NOT NULL,number INTEGER NOT NULL,payload TEXT NOT NULL,hash TEXT NOT NULL,job_id TEXT NOT NULL UNIQUE,coverage TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(date,number));
CREATE TABLE occurrences(scheduled_at TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(id),created_at TEXT NOT NULL);
CREATE TABLE outbox(id TEXT PRIMARY KEY,report_id TEXT NOT NULL REFERENCES reports(id),target TEXT NOT NULL,hash TEXT NOT NULL,body TEXT NOT NULL,state TEXT NOT NULL,part INTEGER NOT NULL,parts INTEGER NOT NULL,provider_id TEXT,error TEXT,created_at TEXT NOT NULL,UNIQUE(report_id,target,hash,part));
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1),body TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE audit(id TEXT PRIMARY KEY,action TEXT NOT NULL,entity_id TEXT,detail TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE characters(id TEXT PRIMARY KEY,name TEXT NOT NULL,body TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE skills(id TEXT PRIMARY KEY,skill_id TEXT NOT NULL,version TEXT NOT NULL,hash TEXT NOT NULL,files TEXT NOT NULL,origin TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE drafts(project_id TEXT NOT NULL REFERENCES projects(id),kind TEXT NOT NULL,body TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL,PRIMARY KEY(project_id,kind));
